arguments.query:
CREATE TABLE IF NOT EXISTS todos (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, status TEXT DEFAULT 'pending', created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS todo_deps (todo_id TEXT, depends_on TEXT, PRIMARY KEY (todo_id, depends_on));
INSERT OR REPLACE INTO todos (id, title, description, status, updated_at) VALUES ('build-form-page', 'Build notification form page', 'Create a standalone HTML document with a React-style component structure, dark theme, one radio-button question inside .form-field, and a submit button saved to index.html.', 'in_progress', CURRENT_TIMESTAMP);

