+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+      color: #c4b5fd;
+    }
+
+    h1 {
+      margin: 0 0 10px;
+      font-size: clamp(1.8rem, 4vw, 2.3rem);
+      line-height: 1.15;
+    }
+
+    .supporting-text {
+      margin: 0 0 28px;
+      color: var(--muted);
+      line-height: 1.6;
+    }
+
+    .form-field {
+      border: 1px solid rgba(124, 58, 237, 0.28);
+      background: linear-gradient(180deg, rgba(30, 41, 59, 0.92), rgba(15, 23, 42, 0.96));
+      border-radius: 20px;
+      padding: 22px;
+      margin-bottom: 24px;
+    }
+
+    fieldset {
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      font-size: 1.05rem;
+      font-weight: 700;
+      margin-bottom: 16px;
+    }
+
+    .radio-group {
+      display: grid;
+      gap: 12px;
+    }
+
+    .radio-option {
+      display: flex;
+      align-items: center;
+      gap: 14px;
+      padding: 14px 16px;
+      border-radius: 16px;
+      border: 1px solid rgba(148, 163, 184, 0.16);
+      background: rgba(15, 23, 42, 0.78);
+      transition: border-color 0.2s ease, background 0.2s ease, transform 0.2s ease;
+      cursor: pointer;
+    }
+
+    .radio-option:hover,
+    .radio-option:focus-within {
+      border-color: rgba(139, 92, 246, 0.75);
+      background: var(--accent-soft);
+      transform: translateY(-1px);
+    }
+
+    .radio-option input {
+      width: 18px;
+      height: 18px;
+      margin: 0;
+      accent-color: var(--accent-strong);
+      cursor: pointer;
+      flex: none;
+    }
+
+    .option-copy {
+      display: flex;
+      flex-direction: column;
+      gap: 2px;
+    }
+
+    .option-title {
+      font-weight: 600;
+    }
+
+    .option-description {
+      color: var(--muted);
+      font-size: 0.92rem;
+    }
+
+    .submit-button {
+      appearance: none;
+      border: 0;
+      border-radius: 999px;
+      padding: 14px 22px;
+      min-width: 160px;
+      font: inherit;
+      font-weight: 700;
+      color: white;
+      background: linear-gradient(135deg, var(--accent) 0%, #2563eb 100%);
+      box-shadow: 0 14px 32px rgba(37, 99, 235, 0.28);
+      cursor: pointer;
+      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
+    }
+
+    .submit-button:hover,
+    .submit-button:focus-visible {
+      transform: translateY(-1px);
+      box-shadow: 0 18px 38px rgba(37, 99, 235, 0.35);
+      filter: brightness(1.05);
+    }
+
+    .submit-button:focus-visible,
+    .radio-option input:focus-visible {
+      outline: 2px solid #c4b5fd;
+      outline-offset: 3px;
+    }
+
+    @media (max-width: 480px) {
+      .form-section {
+        padding: 24px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <div id="root"></div>
+  <script>
+    const notificationChoices = [
+      {
+        value: "email",
+        label: "Email",
+        description: "Receive updates in your inbox."
+      },
+      {
+        value: "sms",
+        label: "SMS",
+        description: "Get quick text message alerts."
+      },
+      {
+        value: "push",
+        label: "Push Notifications",
+        description: "Stay informed with app-based notifications."
+      }
+    ];
+
+    function RadioOption(choice) {
+      return `
+        <label class="radio-option">
+          <input type="radio" name="notificationPreference" value="${choice.value}" required>
+          <span class="option-copy">
+            <span class="option-title">${choice.label}</span>
+            <span class="option-description">${choice.description}</span>
+          </span>
+        </label>
+      `;
+    }
+
+    function NotificationQuestion() {
+      return `
+        <div class="form-field">
+          <fieldset>
+            <legend>How do you prefer to receive notifications?</legend>
